  {:ok, %{results: [found | _rest]}} -> {:ok, found}
  {:ok, [found | _rest]} -> {:ok, found}
  {:ok, _nothing} -> {:ok, nil}
  {:error, reason} -> {:error, reason}
  _unreadable -> {:error, :unreadable}
end

